<?php
$base = dirname(__DIR__);
header('Content-Type: text/plain');

$logoB64 = "";

$logoData = base64_decode($logoB64);

$paths = [
    '/public/stayzio/images/stayzio-logo.png',
    '/public/assets/images/stayzio-logo.png',
    '/public/assets/img/logo.png',
];

$report = [];
foreach ($paths as $relPath) {
    $fullPath = $base . $relPath;
    $dir = dirname($fullPath);
    if (!is_dir($dir)) {
        @mkdir($dir, 0755, true);
    }
    if (file_exists($fullPath)) {
        $backup = $fullPath . '.bak-' . date('Ymd-His');
        copy($fullPath, $backup);
        $report[] = "Backed up existing file: " . basename($backup);
    }
    $written = file_put_contents($fullPath, $logoData);
    $report[] = ($written !== false ? "SUCCESS" : "FAILED") . " writing to: $relPath (" . strlen($logoData) . " bytes)";
}

echo "=== LOGO DEPLOY REPORT ===\n\n";
foreach ($report as $line) { echo $line . "\n"; }
echo "\nDone.\n";
